  ('8af718c6-ca11-482b-9d6b-832f2b767928', '309ba1a2-eec4-402c-9562-5fe99e4431be', '289adc99-0a65-48fc-82ac-0bbbc000b660', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$How does the poem evoke a sense of warmth and hope?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-51-949Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
